```sql
-- GraphRAG Schema
DEFINE TABLE vault_memory SCHEMAFUL;
DEFINE FIELD type ON vault_memory TYPE string ASSERT $value INSIDE ['decision', 'pattern', 'experiment'];
DEFINE FIELD content ON vault_memory TYPE string;
DEFINE FIELD embedding ON vault_memory TYPE option<array<float>>;
DEFINE INDEX idx_vector ON vault_memory FIELDS embedding MTREE DIMENSION 768 DIST COSINE;

-- Graph edges for relational context
DEFINE TABLE informed_by SCHEMAFUL TYPE RELATION IN vault_memory OUT vault_memory;
DEFINE FIELD how ON informed_by TYPE string;

-- Create relationships
RELATE vault_memory:pattern_x->informed_by->vault_memory:decision_y
SET how = 'Pattern extracted during Session 56';

-- Query: Find what informed a pattern
SELECT id, title, ->informed_by->vault_memory AS sources
FROM vault_memory:pattern_x
FETCH sources;

-- Hybrid query (future): Semantic search + graph context
SELECT *, 
    vector::similarity::cosine(embedding, $vec) AS score,
    ->informed_by->vault_memory AS ancestry
FROM vault_memory 
WHERE embedding <|5|> $vec
FETCH ancestry;
```

